            "Draw" => [0xd824,0xd825,0xd83a,0xd83b,0xd844,0xd845,0xd84c,0xd84d,0xd854,0xd855,0xd85c,0xd85d,0xd860,0xd861,0xd864,0xd865,0xd868,0xd869,0xd86c,0xd86d,0xd87a,0xd87b,0xd88e,0xd88f,0xd892,0xd893,0xd898,0xd899,0xd89c,0xd89d,0xd8a0,0xd8a1,0xd8a6,0xd8a7,0xd8aa,0xd8ab,0xd8ae,0xd8af,0xd8b6,0xd8b7,0xd8ba,0xd8bb,0xd8be,0xd8bf,0xd8d5,0xd8d6,0xd8d9,0xd8da,0xd8f5,0xd8f6,0xd905,0xd906,0xd909,0xd90a,0xd90d,0xd90e,0xd911,0xd912,0xd92b,0xd92c,0xd93b,0xd93c,0xd93f,0xd940,0xd943,0xd944,0xd947,0xd948,0xd95b,0xd95c,0xd971,0xd972,0xd97b,0xd97c,0xd983,0xd984,0xd98b,0xd98c,0xd993,0xd994,0xd997,0xd998,0xd99b,0xd99c,0xd99f,0xd9a0,0xd9a3,0xd9a4,0xd9b1,0xd9b2,0xd9c5,0xd9c6,0xd9c9,0xd9ca,0xd9cf,0xd9d0,0xd9d3,0xd9d4,0xd9d7,0xd9d8,0xd9dd,0xd9de,0xd9e1,0xd9e2,0xd9e5,0xd9e6,0xd9ed,0xd9ee,0xd9f1,0xd9f2,0xd9f5,0xd9f6,0xda0c,0xda0d,0xda10,0xda11,0xda2c,0xda2d,0xda3c,0xda3d,0xda40,0xda41,0xda44,0xda45,0xda48,0xda49,0xda62,0xda63,0xda72,0xda73,0xda76,0xda77,0xda7a,0xda7b,0xda7e,0xda7f],
