            "Callback" => [0xd836,0xd837,0xd901,0xd902,0xd937,0xd938,0xd96d,0xd96e,0xda38,0xda39,0xda6e,0xda6f],
            "Columns" => [0xd828,0xd83e,0xd870,0xd8ef,0xd915,0xd925,0xd94b,0xd95f,0xd975,0xd9a7,0xda26,0xda4c,0xda5c,0xda82],
            "Rows" => [0xd829,0xd83f,0xd871,0xd8f0,0xd916,0xd926,0xd94c,0xd960,0xd976,0xd9a8,0xda27,0xda4d,0xda5d,0xda83],
            "Attack" => [0xd848,0xd849,0xd850,0xd851,0xd858,0xd859,0xd97f,0xd980,0xd987,0xd988,0xd98f,0xd990],
            "Sweat" => [0xd8b2,0xd8b3,0xd9e9,0xd9ea],
            "Sound" => [0xd882,0xd9b9],
            "HitCount" => [0xd889,0xd9c0],
            "LoopCount" => [0xd8d2,0xda09],
            _ => throw new InvalidOperationException("Unknown eye-door proof field."),
        };
        if (field == "Control")
            for (int raw = 0; raw <= ushort.MaxValue; raw++)
            {
                bool byteOwned = raw >= 0xd81e && raw <= 0xda8b;
                bool wordOwned = raw >= 0xd81e && raw < 0xda8b;
                AssertEqual(byteOwned,EyeDoorPlmProgramDefinitions.TryReadMechanicsByte((ushort)raw,out byte b),"Eye door full byte domain");
                AssertEqual(wordOwned,EyeDoorPlmProgramDefinitions.TryReadMechanicsWord((ushort)raw,out ushort w),"Eye door full word domain");
                if (!byteOwned) AssertEqual((byte)0,b,"Eye door rejected byte output");
                if (!wordOwned) AssertEqual((ushort)0,w,"Eye door rejected word output");
            }
        foreach (ushort address in addresses)
        {
            AssertTrue(EyeDoorPlmProgramDefinitions.TryReadMechanicsByte(address,out byte b),"Eye door owned native field byte");
            AssertEqual(rom.ReadByte(0x840000 | address),b,"Eye door original " + field + " byte");
            AssertTrue(RoomPlmProgramDefinitions.TryReadByte(address,out byte combinedByte),"Eye door composed byte ownership");
            AssertEqual(rom.ReadByte(0x840000 | address),combinedByte,"Eye door original composed " + field + " byte");
            if (address == 0xda8b) continue;
            AssertTrue(EyeDoorPlmProgramDefinitions.TryReadMechanicsWord(address,out ushort w),"Eye door owned overlapping native word");
            AssertEqual(ReadSamusEaterPlmWord(rom,0x840000 | address),w,"Eye door original " + field + " overlapping word");
            AssertTrue(RoomPlmProgramDefinitions.TryReadWord(address,out ushort combinedWord),"Eye door composed word ownership");
            AssertEqual(ReadSamusEaterPlmWord(rom,0x840000 | address),combinedWord,"Eye door original composed " + field + " overlapping word");
        }
    }
}